import React, { useState, useRef, useEffect } from 'react';

interface ChatInputProps {
  onSend: (question: string, description: string) => void;
  disabled?: boolean;
}

export const ChatInput: React.FC<ChatInputProps> = ({ onSend, disabled }) => {
  const [content, setContent] = useState('');
  const [extra, setExtra] = useState('');
  const [showExtra, setShowExtra] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const adjustHeight = () => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  };

  useEffect(() => {
    adjustHeight();
  }, [content]);

  const submit = () => {
    if (content.trim() && !disabled) {
      onSend(content.trim(), extra.trim());
      setContent('');
      setExtra('');
      setShowExtra(false);
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    submit();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submit();
    }
  };

  return (
    <div className="chat-input">
      <form onSubmit={handleSubmit} className="input-box">
        <textarea
          ref={textareaRef}
          value={content}
          onChange={(e) => setContent(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="说说你的困扰吧，我会认真倾听…"
          rows={1}
          disabled={disabled}
          aria-label="输入你的问题"
        />
        {showExtra && (
          <div className="chat-input-extra">
            <textarea
              value={extra}
              onChange={(e) => setExtra(e.target.value)}
              placeholder="可选：补充背景（如持续时间、具体情境）"
              rows={2}
              disabled={disabled}
              aria-label="补充描述"
            />
          </div>
        )}
        <div className="input-box-footer">
          <button
            type="button"
            className="chat-toggle-extra"
            onClick={() => setShowExtra((v) => !v)}
            disabled={disabled}
          >
            {showExtra ? '收起补充说明' : '+ 补充背景（可选）'}
          </button>
          <span className="input-hint">Enter 发送 · Shift+Enter 换行</span>
          <button
            type="submit"
            className="send-btn"
            disabled={disabled || !content.trim()}
            aria-label="发送消息"
          >
            <span className="send-btn-text">发送</span>
            <span className="send-btn-icon" aria-hidden="true">
              ↑
            </span>
          </button>
        </div>
      </form>
    </div>
  );
};
